export const ACTION_03_PROMPT_VERSION = "1.0.0";

export interface PrioritizationContext {
  extractedIssues: Array<{
    id: string;
    title: string;
    description: string;
    category: string;
    affectedArea: string;
    detectedAt: string;
  }>;
  priorityRules: {
    criticalityFactors: string[];
    urgencyFactors: string[];
    riskFactors: string[];
    scoreThresholds: {
      critical: number;
      high: number;
      medium: number;
      low: number;
    };
  };
  historicalContext?: {
    similarIssuesCount: number;
    recurrencePattern: string;
    averageResolutionTime: number;
  };
}

export interface PrioritizationResult {
  issueId: string;
  priorityScore: number;
  priorityLevel: "critical" | "high" | "medium" | "low";
  reasoning: string;
  recommendedAction: string;
  escalationRequired: boolean;
}

export function buildAction03Prompt(context: PrioritizationContext): string {
  const issuesJson = JSON.stringify(context.extractedIssues, null, 2);
  const rulesJson = JSON.stringify(context.priorityRules, null, 2);
  const historicalJson = context.historicalContext
    ? JSON.stringify(context.historicalContext, null, 2)
    : "なし";

  return `# Action 3: 課題の優先順位付与プロンプト

## 目的
抽出された課題に対して、重要度（Criticality）と緊急度（Urgency）に基づいて優先度スコアを自動計算し、優先度レベルを判定する。

## 入力データ

### 抽出済み課題リスト
\`\`\`json
${issuesJson}
\`\`\`

### 優先度付与ルール
\`\`\`json
${rulesJson}
\`\`\`

### 過去の類似課題コンテキスト
\`\`\`json
${historicalJson}
\`\`\`

## 優先度スコアリング基準

### 重要度（Criticality）の評価軸
- **影響範囲**: 単一ユーザー（1点）→ チーム（3点）→ 部門（5点）→ 全社（10点）
- **ビジネスインパクト**: 軽微（1点）→ 中程度（3点）→ 重大（5点）→ 致命的（10点）
- **データ/セキュリティリスク**: なし（0点）→ 低（2点）→ 中（5点）→ 高（10点）

### 緊急度（Urgency）の評価軸
- **対応期限**: 1週間以上（1点）→ 3日以内（3点）→ 24時間以内（5点）→ 即座（10点）
- **既知の回避策**: あり（-2点）→ なし（0点）
- **ユーザー報告数**: 1件（1点）→ 3件以上（3点）→ 10件以上（5点）

### 再発リスク（Recurrence Risk）の評価軸
- **過去の発生回数**: 初回（0点）→ 2回目（2点）→ 3回以上（5点）
- **解決期間**: 短期解決済み（0点）→ 長期未解決（3点）

## スコア計算ロジック

1. 各課題について、重要度スコア（C）、緊急度スコア（U）、再発リスク（R）を算出
2. 総合優先度スコア = (C × 0.4) + (U × 0.4) + (R × 0.2)
3. スコアに基づいて優先度レベルを判定:
   - Critical: スコア ≥ ${context.priorityRules.scoreThresholds.critical}
   - High: ${context.priorityRules.scoreThresholds.high} ≤ スコア < ${context.priorityRules.scoreThresholds.critical}
   - Medium: ${context.priorityRules.scoreThresholds.medium} ≤ スコア < ${context.priorityRules.scoreThresholds.high}
   - Low: スコア < ${context.priorityRules.scoreThresholds.medium}

## 出力形式

各課題について、以下の JSON 形式で優先度判定結果を出力してください:

\`\`\`json
{
  "issueId": "課題ID",
  "priorityScore": 0.0,
  "priorityLevel": "critical|high|medium|low",
  "reasoning": "優先度判定の根拠（重要度・緊急度・再発リスクの観点から）",
  "recommendedAction": "推奨対応方針（即座対応/本日中対応/週内対応/計画対応など）",
  "escalationRequired": true|false
}
\`\`\`

## エスカレーション判定基準

以下のいずれかに該当する場合、escalationRequired を true に設定してください:

1. priorityLevel が "critical" の場合
2. 複数部門にまたがる課題の場合
3. 経営判断が必要な重大課題の場合
4. 過去の類似課題で対応方針が定まっていない場合
5. 推奨対応方針が標準ルールに該当しない場合

## 注意事項

- スコア計算は客観的な基準に基づいて実施し、恣意的な判定を避ける
- 同一課題が複数件報告されている場合は、統合判定を検討する
- 過去の類似課題の解決期間を参考に、対応の難易度を考慮する
- 優先度判定の根拠は、部長の確認時に説明できる程度に詳細に記述する

## 処理フロー

1. 各課題の重要度スコアを計算
2. 各課題の緊急度スコアを計算
3. 各課題の再発リスクスコアを計算
4. 総合優先度スコアを計算
5. 優先度レベルを判定
6. エスカレーション要否を判定
7. 推奨対応方針を決定
8. 結果を JSON 形式で出力

すべての課題について、上記の処理を実施し、優先度順にソートした結果を返してください。`;
}
